<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Conscription\ModelBoundOperationalProfileQualificationService as S;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\{InputArgument,InputInterface,InputOption};use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:conscription:qualify-model-bound-operational-profile')]final class ConscriptionQualifyModelBoundOperationalProfileCommand extends Command{public function __construct(private readonly S$s){parent::__construct();}protected function configure():void{$this->addArgument('approval-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->qualify((string)$i->getArgument('approval-id'),new \DateTimeImmutable());}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>MODEL_BOUND_PROFILE_OPERATIONALLY_QUALIFIED</info> '.$r['qualification_id']);return self::SUCCESS;}}
